//! ✂️ All schedule families retain every declared consumer guard and exact original recreation stack through bounded native closure.
use crate::snapshot::original::EnergyModelSnapshot;
#[path="../../../🌱️construction/🧪️tests/🧰️leaf/🦀️.rs"]mod laws;
#[derive(Debug,semio_framework_value::ToValue,semio_framework_value::FromValue,semio_framework_value::RetireOwned)]
#[value(tag="mutation",rename_all="camelCase")]
enum Operation{CreateConstantSchedule(crate::CreateConstantSchedule),DeleteConstantSchedule(crate::DeleteConstantSchedule),CreateDailySchedule(crate::CreateDailySchedule),DeleteDailySchedule(crate::DeleteDailySchedule),CreateWeeklySchedule(crate::CreateWeeklySchedule),DeleteWeeklySchedule(crate::DeleteWeeklySchedule),CreateAnnualSchedule(crate::CreateAnnualSchedule),DeleteAnnualSchedule(crate::DeleteAnnualSchedule),CreateTimeSeriesSchedule(crate::CreateTimeSeriesSchedule),DeleteTimeSeriesSchedule(crate::DeleteTimeSeriesSchedule),InsertAnnualScheduleRule(crate::InsertAnnualScheduleRule),AddAnnualScheduleHoliday(crate::AddAnnualScheduleHoliday),RemoveAnnualScheduleRule(crate::RemoveAnnualScheduleRule),RemoveAnnualScheduleHoliday(crate::RemoveAnnualScheduleHoliday)}
macro_rules! from{($($name:ident),*)=>{$(impl From<crate::$name> for Operation{fn from(v:crate::$name)->Self{Self::$name(v)}})*}}
from!(CreateConstantSchedule,DeleteConstantSchedule,CreateDailySchedule,DeleteDailySchedule,CreateWeeklySchedule,DeleteWeeklySchedule,CreateAnnualSchedule,DeleteAnnualSchedule,CreateTimeSeriesSchedule,DeleteTimeSeriesSchedule,InsertAnnualScheduleRule,AddAnnualScheduleHoliday,RemoveAnnualScheduleRule,RemoveAnnualScheduleHoliday);
impl protocol::Mutation<EnergyModelSnapshot> for Operation{type Diff=crate::diff::original::EnergyModelDiff;const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[];fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{panic!("native schedule deletion laws use original authored leaves")}}
fn identity(v:&Operation)->u32{match v{Operation::CreateConstantSchedule(p)=>p.id.0,Operation::CreateDailySchedule(p)=>p.id.0,Operation::CreateWeeklySchedule(p)=>p.id.0,Operation::CreateAnnualSchedule(p)=>p.id.0,Operation::CreateTimeSeriesSchedule(p)=>p.id.0,Operation::InsertAnnualScheduleRule(p)=>p.id.0,Operation::AddAnnualScheduleHoliday(p)=>p.id.0,_=>panic!("schedule deletion emits only its exact original restoration intents")}}
macro_rules! ids{($p:ident,$field:ident)=>{{let rows=&$p.model.outputs.get().schedules.get().$field;(0..rows.len()).map(|i|rows.get(i).unwrap().id.0).collect()}}}
fn run(kind:&str,fixture:&serde_json::Value){let input=serde_json::to_string(fixture).unwrap();match kind{"Constant"=>laws::run::<crate::DeleteConstantSchedule,Operation>(&input,|p|ids!(p,constants),identity),"Daily"=>laws::run::<crate::DeleteDailySchedule,Operation>(&input,|p|ids!(p,daily),identity),"Weekly"=>laws::run::<crate::DeleteWeeklySchedule,Operation>(&input,|p|ids!(p,weekly),identity),"Annual"=>laws::run::<crate::DeleteAnnualSchedule,Operation>(&input,|p|ids!(p,annual),identity),"TimeSeries"=>laws::run::<crate::DeleteTimeSeriesSchedule,Operation>(&input,|p|ids!(p,time_series),identity),_=>unreachable!()}}
fn fixture(law:&serde_json::Value,kind:&serde_json::Value)->serde_json::Value{let collection=kind["collection"].as_str().unwrap();let target=kind["target"].as_u64().unwrap();let rows=&law["rows"][collection];let after=rows.as_array().unwrap().iter().filter(|r|r["id"]!=target).map(|r|r["id"].clone()).collect::<Vec<_>>();serde_json::json!({"collection":format!("schedules.{collection}"),"existingRows":rows,"model":{"schedules":law["rows"]},"cancelAt":law["cancelAt"],"maximumTurns":law["maximumTurns"],"cases":[{"payload":{"id":target},"outcome":"changed","after":after,"inverseCount":kind["inverse"].as_array().unwrap().len(),"inverseSteps":kind["inverse"]},{"payload":{"id":999},"outcome":"missing"}]})}
#[test]fn five_original_schedule_deletions_preserve_actual_rank_complete_fields_inverse_and_cancelled_prefixes(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for kind in law["kinds"].as_array().unwrap(){run(kind["kind"].as_str().unwrap(),&fixture(&law,kind));}}
#[test]fn all_twenty_original_schedule_reference_sources_refuse_each_schedule_family_before_removal(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for kind in law["kinds"].as_array().unwrap(){for reference in law["references"].as_array().unwrap(){let mut fixture=fixture(&law,kind);let target=&kind["target"];let r=&reference["source"];let collection=r["collection"].as_str().unwrap();let field=r["field"].as_str().unwrap();let mut row=reference["row"].clone();match r["storage"].as_str().unwrap(){"direct"|"shared-optional"=>row[field]=target.clone(),"shared-array"=>*row[field].as_array_mut().unwrap().last_mut().unwrap()=target.clone(),"shared-record-array"=>row[field].as_array_mut().unwrap().last_mut().unwrap()[r["member"].as_str().unwrap()]=target.clone(),_=>unreachable!()};if r.get("nested").is_some(){fixture["model"]["schedules"][collection][0]=row;let selected=kind["collection"].as_str().unwrap();fixture["existingRows"]=fixture["model"]["schedules"][selected].clone();}else{fixture["model"][collection]=serde_json::json!([row]);}fixture["cancelAt"]=serde_json::json!([0,127]);fixture["cases"]=serde_json::json!([{"payload":{"id":target},"outcome":"referenced"}]);run(kind["kind"].as_str().unwrap(),&fixture);}}}

fn apply<L>(snapshot:Box<EnergyModelSnapshot>,payload:L,with_inverse:bool)->(Box<EnergyModelSnapshot>,Vec<Operation>)where L:protocol::RetainedMutationLeaf<EnergyModelSnapshot,Operation>+semio_framework_value::retirement::RetireOwned+Sync{
 use protocol::{RetainedMutationLeafPreparation,RetainedMutationAdvance,RetainedMutationDecision,RetainedMutationCloseContext};use super::helpers::{source,projected_source,grant,observe,drain,project_record,central_fragment};
 let original=projected_source(snapshot);let input=source(payload);let mut owner=L::Preparation::new();let mut ready=false;for _ in 0..100000{let d=owner.decision_demand(input.borrow(),original.borrow(),4096).unwrap();let g=grant(d);let(s,h)=observe(||owner.decide(input.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){ready=true;break;}}assert!(ready);let value=match owner.take_decision(){RetainedMutationDecision::Admitted(value,messages)=>{assert!(messages.is_empty());drain(messages);source(value)},RetainedMutationDecision::Refused(messages)=>panic!("original schedule restoration refused: {:?}",messages)};
 let mut inverse=Vec::new();if with_inverse{let mut ready=false;for _ in 0..100000{let d=owner.inverse_demand(input.borrow(),original.borrow(),value.borrow(),4096).unwrap();let g=grant(d);let(s,h)=observe(||owner.inverse(input.borrow(),original.borrow(),value.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){ready=true;break;}}assert!(ready);inverse=owner.take_inverse();}
 let mut post=project_record(original.borrow());assert!(central_fragment(&value,original.borrow(),&mut post));let factory=semio_framework_value::factory::OwnedValueRetirementFactory::<Operation>::default();let cx=RetainedMutationCloseContext{mutations:&factory};owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let g=grant(owner.close_demand(cx,4096).unwrap());let(s,h)=observe(||owner.close_step(cx,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));drain(value);drain(input);drain(original);(post,inverse)
}
#[test]fn original_annual_inverse_pop_consumer_restores_nonempty_rules_holidays_fallbacks_and_rank(){
 use semio_framework_value::ToValue;use super::helpers::{receive,drain,assert_portable_value};let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut doc:serde_json::Value=serde_json::from_str(include_str!("../../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut doc=doc["document"].take();doc["model"]=super::helpers::corpus()["model"].clone();doc["model"]["schedules"]=law["rows"].clone();let original=Box::new(receive::<EnergyModelSnapshot>(&doc));let expected=original.model.outputs.get().schedules.get().to_value();let(mut restored,mut inverse)=apply(original,crate::DeleteAnnualSchedule{id:crate::schedule::ScheduleId(401)},true);assert_eq!(inverse.len(),5);assert_eq!(restored.model.outputs.get().schedules.get().annual.len(),2);
 while let Some(operation)=inverse.pop(){restored=match operation{Operation::CreateAnnualSchedule(p)=>apply(restored,p,false).0,Operation::InsertAnnualScheduleRule(p)=>apply(restored,p,false).0,Operation::AddAnnualScheduleHoliday(p)=>apply(restored,p,false).0,_=>panic!("annual original inverse contains an unrelated intent")};}
 let expected:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(&expected)).unwrap();assert_portable_value(restored.model.outputs.get().schedules.get().to_value(),&expected);drain(inverse);drain(restored);
}

#[test]fn wide_original_annual_schedule_deletion_emits_every_genuine_inverse_intent_and_closes_all_prefixes(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let kind=law["kinds"].as_array().unwrap().iter().find(|k|k["kind"]=="Annual").unwrap();let mut fixture=fixture(&law,kind);let count=law["wideRuleCount"].as_u64().unwrap()as usize;let sample=law["rows"]["annual"][1]["rules"].as_array().unwrap();let rules=(0..count).map(|rank|sample[rank%sample.len()].clone()).collect::<Vec<_>>();fixture["model"]["schedules"]["annual"][1]["rules"]=serde_json::json!(rules);fixture["existingRows"]=fixture["model"]["schedules"]["annual"].clone();fixture["receivingPolicy"]=law["wideSourceAdmission"].clone();let mut inverse=vec![kind["inverse"].as_array().unwrap().last().unwrap().clone()];for(index,rule)in rules.iter().enumerate(){inverse.push(serde_json::json!({"mutation":"insertAnnualScheduleRule","id":401,"index":index,"startMonth":rule["start_month"],"startDay":rule["start_day"],"endMonth":rule["end_month"],"endDay":rule["end_day"],"dailyScheduleId":rule["daily_schedule_id"]}));}for(index,date)in law["rows"]["annual"][1]["holiday_dates"].as_array().unwrap().iter().enumerate(){inverse.push(serde_json::json!({"mutation":"addAnnualScheduleHoliday","id":401,"index":index,"year":date[0],"month":date[1],"day":date[2]}));}inverse.reverse();fixture["cases"][0]["inverseCount"]=serde_json::json!(inverse.len());fixture["cases"][0]["inverseSteps"]=serde_json::json!(inverse);run("Annual",&fixture);}
